#include <stdio.h>
void f(int a[4]){ printf("in f: %zu\n", sizeof(a)); /* really int* */ }
int main(void){
  int a[4]={1,2,3,4};
  printf("in main: %zu vs pointer %zu\n", sizeof(a), sizeof(&a[0]));
  f(a);
  char *lit="hi"; char arr[]="hi";
  printf("lit pointer %zu arr bytes %zu\n", sizeof(lit), sizeof(arr));
  return 0;
}

#include <stddef.h>
#include <stdint.h>
static uint8_t heap[1<<20];
static size_t off=0;
void* bump_alloc(size_t n){
  size_t aligned=(n+7)&~(size_t)7;
  if(off+aligned> sizeof(heap)) return 0;
  void *p=&heap[off]; off+=aligned; return p;
}
void bump_reset(void){ off=0; }
// use: int *v=bump_alloc(100*sizeof(int)); ... bump_reset();
